    dust2::r::read_real_array(parameters, shared.dim.Su, shared.unhosp_mortality.data(), "unhosp_mortality", false);
    dust2::r::read_real_array(parameters, shared.dim.Su, shared.hosp_duration.data(), "hosp_duration", false);
    dust2::r::read_real_array(parameters, shared.dim.Su, shared.comm_mortality.data(), "comm_mortality", false);
    dust2::r::read_real_array(parameters, shared.dim.kappa_E, shared.kappa_E.data(), "kappa_E", false);
    dust2::r::read_real_array(parameters, shared.dim.kappa_E, shared.kappa_C.data(), "kappa_C", false);
    dust2::r::read_real_array(parameters, shared.dim.kappa_E, shared.kappa_H.data(), "kappa_H", false);
