    internal.hosp_rem[0] = shared.hosp_capacity;
    for (size_t i = 2; i <= static_cast<size_t>(shared.n_age); ++i) {
      internal.hosp_rem[i - 1] = monty::math::max<real_type>(0, internal.hosp_rem[i - 1 - 1] - internal.hosp_required[shared.n_age - i + 2 - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.lambda_E[i - 1] = dust2::array::sum<real_type>(internal.lambda_Eu.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1}) + dust2::array::sum<real_type>(internal.lambda_Ev.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1});
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.lambda_C[i - 1] = dust2::array::sum<real_type>(internal.lambda_Cu.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1}) + dust2::array::sum<real_type>(internal.lambda_Cv.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1});
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.lambda_H[i - 1] = dust2::array::sum<real_type>(internal.lambda_Hu.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1}) + dust2::array::sum<real_type>(internal.lambda_Hv.data(), shared.dim.kappa_E, {i - 1, i - 1}, {0, shared.dim.kappa_E.dim[1] - 1});
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.hospitalised[i - 1] = ((shared.hosp_prioritised ? (monty::math::min<real_type>(internal.hosp_required[i - 1], internal.hosp_rem[shared.n_age - i + 1 - 1])) : ((hosp_required_total > 0 ? (shared.hosp_capacity * internal.hosp_required[i - 1] / hosp_required_total) : 0))));
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.p_Eu_exit[i - 1] = 1 - monty::math::exp<real_type>(-(shared.sigma_Eu[i - 1] + shared.eta_Eu[i - 1]) * dt);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.p_Ev_exit[i - 1] = 1 - monty::math::exp<real_type>(-(shared.sigma_Ev[i - 1] + shared.eta_Ev[i - 1]) * dt);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.p_Cu_exit[i - 1] = 1 - monty::math::exp<real_type>(-(shared.gamma_Cu[i - 1] + shared.mu_Cu[i - 1]) * dt);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.p_Cv_exit[i - 1] = 1 - monty::math::exp<real_type>(-(shared.gamma_Cv[i - 1] + shared.mu_Cv[i - 1]) * dt);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.lambda_u[i - 1] = shared.p_trans * (internal.lambda_E[i - 1] + internal.lambda_C[i - 1] + internal.lambda_H[i - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.lambda_v[i - 1] = shared.p_trans * (1 - shared.vax_infection) * (internal.lambda_E[i - 1] + internal.lambda_C[i - 1] + internal.lambda_H[i - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.total_hosp_mortality[i - 1] = ((internal.hosp_required[i - 1] > 0 ? ((shared.hosp_mortality[i - 1] * internal.hospitalised[i - 1] + shared.unhosp_mortality[i - 1] * (internal.hosp_required[i - 1] - internal.hospitalised[i - 1])) / internal.hosp_required[i - 1]) : shared.hosp_mortality[i - 1]));
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.n_Eu_exit[i - 1] = monty::random::binomial<real_type>(rng_state, Eu[i - 1], internal.p_Eu_exit[i - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.n_Ev_exit[i - 1] = monty::random::binomial<real_type>(rng_state, Ev[i - 1], internal.p_Ev_exit[i - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.n_Cu_exit[i - 1] = monty::random::binomial<real_type>(rng_state, Cu[i - 1], internal.p_Cu_exit[i - 1]);
    }
    for (size_t i = 1; i <= shared.dim.Su.size; ++i) {
      internal.n_Cv_exit[i - 1] = monty::random::binomial<real_type>(rng_state, Cv[i - 1], internal.p_Cv_exit[i - 1]);
    }
